tex.x leq y\nleq z\nleq w by algebra:
\begin{align*}
  x &\leq y \\
    &\leq z \\
    &\leq w&&\text{ by algebra}
\end{align*}

tex.5+7 = 12 by arithmetic\ncong_(3) 0 // 12:
\begin{align*}
  5+7 &=12&&\text{ by arithmetic} \\
    &\underset{3}{\equiv}0&&\textcolor{black}{\text{ 12 is a multiple of 3}}
\end{align*}

tex.m | n by thm1\n| p // divisibility is tr:
\begin{align*}
  m &\mid n&&\text{ by thm1} \\
    &\mid p&&\textcolor{black}{\text{ divisibility is transitive}} \\
    &=q
\end{align*}

tex.A subset B // A is contained in B\nsubse:
\begin{align*}
  A &\subseteq B&&\textcolor{black}{\text{ A is contained in B}} \\
