tex.a cong b by SAS\ncong c // congruence is:
\begin{align*}
  a &\cong b&&\text{ by SAS} \\
    &\cong c&&\textcolor{black}{\text{ congruence is transitive}} \\
    &=d&&\text{ by defn}
\end{align*}

